const states=[['idle','Спокойствие'],['happy','Радость'],['sad','Грусть'],['sleep','Сон'],['study','Изучение'],['wow','Восторг'],['like','Одобрение'],['party','Праздник'],['wave','Приветствие'],['laugh','Смех']];
const canvas=document.querySelector('canvas'),fallback=document.querySelector('#fallback'),container=document.querySelector('.mascot'),list=document.querySelector('.emotions'),pause=document.querySelector('#pause');
let player=null,active=0,ready=false,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,equipped={collar:null,glasses:null,hat:null},catalog=[],slot="collar";
rive.RuntimeLoader.setWasmUrl('assets/rive.wasm');
new ResizeObserver(()=>player?.resizeDrawingSurfaceToCanvas()).observe(canvas);
function pauseIcon(){pause.innerHTML=paused?'<svg width="16" height="16" viewBox="0 0 16 16"><path d="M5 3l8 5-8 5z" fill="currentColor"/></svg>':'<svg width="16" height="16" viewBox="0 0 16 16"><path d="M5 3v10M11 3v10" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>';pause.setAttribute('aria-label',paused?'Продолжить анимацию':'Приостановить анимацию');pause.title=pause.getAttribute('aria-label')}
function select(index){const previous=states[active][0];active=index;const [id,label]=states[index];fallback.src=`assets/v3/${id}.png`;fallback.alt=`Маскот — ${label.toLowerCase()}`;canvas.setAttribute('aria-label',fallback.alt);document.querySelector('#current').textContent=label;document.querySelector('#counter').textContent=String(index+1).padStart(2,'0')+' / 10';list.querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-pressed',i===index));if(!ready)return;player.stop(previous);player.play(id);if(paused)player.pause(id);document.body.dataset.loaded=id;}
const slotLabels={collar:'Ошейники',glasses:'Очки',hat:'Шапки'};
function applyWearable(){if(!ready)return;for(const category of Object.keys(slotLabels)){const items=catalog.filter(x=>x.slot===category);player.stop(['slot-'+category+'-none',...items.map(x=>x.animation)]);const item=items.find(x=>x.id===equipped[category]);player.play(item?item.animation:'slot-'+category+'-none');}if(paused)player.pause();}
function renderCloset(){const tabs=document.querySelector('#slots');tabs.replaceChildren();for(const category of Object.keys(slotLabels)){const b=document.createElement('button');b.textContent=slotLabels[category];b.setAttribute('aria-pressed',category===slot);b.onclick=()=>{slot=category;renderCloset()};tabs.append(b);}const el=document.querySelector('#wearables');el.replaceChildren();const none=document.createElement('button');none.className='wearable itemchip';none.innerHTML='<span class="empty-item">∅</span><span>Без вещи</span>';none.setAttribute('aria-pressed',!equipped[slot]);none.onclick=()=>equip(null,slot);el.append(none);for(const item of catalog.filter(x=>x.slot===slot)){const b=document.createElement('button');b.className='wearable itemchip';b.disabled=!item.unlocked;b.title=item.name;b.setAttribute('aria-pressed',equipped[slot]===item.id);b.setAttribute('aria-label',item.name+(item.unlocked?'':' — заблокировано'));b.innerHTML=`<img src="${item.file}" alt=""><span>${item.name}</span>${item.unlocked?'':'<span class="locked">Закрыто</span>'}`;b.onclick=()=>equip(item.id);el.append(b);}document.querySelector('.wardrobe-count').textContent=Object.values(equipped).filter(Boolean).length?('Надето: '+Object.values(equipped).filter(Boolean).length):'22 вещи';}
function equip(id,category=slot){if(id!==null){const item=catalog.find(x=>x.id===id&&x.unlocked);if(!item)return false;category=item.slot;}equipped[category]=id;renderCloset();applyWearable();return true;}
window.mascotWardrobe={getState:()=>({equipped:{...equipped},items:catalog.map(x=>({...x}))}),equip,setUnlocked:(id,unlocked)=>{const item=catalog.find(x=>x.id===id);if(!item)return false;item.unlocked=!!unlocked;if(!item.unlocked&&equipped[item.slot]===id)equip(null,item.slot);renderCloset();return true;}};
document.querySelector('#clear-outfit').onclick=()=>{equipped={collar:null,glasses:null,hat:null};renderCloset();applyWearable()};
states.forEach(([id,label],i)=>{const b=document.createElement('button');b.className='emotion';b.setAttribute('aria-pressed',i===0);b.innerHTML=`<img src="assets/v3/${id}.png" alt="" draggable="false"><span>${label}</span>`;b.addEventListener('click',()=>select(i));b.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%states.length;if(e.key==='ArrowLeft')next=(i+states.length-1)%states.length;if(e.key==='Home')next=0;if(e.key==='End')next=states.length-1;if(next!==undefined){e.preventDefault();list.children[next].focus();select(next)}});list.append(b)});
pause.addEventListener('click',()=>{paused=!paused;if(paused)player?.pause();else{player?.play(states[active][0]);applyWearable()}pauseIcon()});document.querySelector('#replay').addEventListener('click',()=>{paused=false;pauseIcon();select(active)});document.addEventListener('visibilitychange',()=>{if(document.hidden)player?.pause();else if(!paused){player?.play(states[active][0]);applyWearable()}});
async function start(){try{const res=await fetch('assets/v3/rig.json');if(!res.ok)throw new Error('Rig manifest failed');const rig=await res.json();catalog=rig.accessories;renderCloset();player=new rive.Rive({src:'assets/v3/mascot.riv?v=3.3',artboard:'Mascot',canvas,autoplay:true,animations:[states[active][0],'wear-none','slot-collar-none','slot-glasses-none','slot-hat-none'],layout:new rive.Layout({fit:rive.Fit.Contain,alignment:rive.Alignment.Center}),onLoad:()=>{ready=true;player.resizeDrawingSurfaceToCanvas();select(active);applyWearable();container.classList.add('ready');document.body.dataset.engine='rive-continuous-mesh-v3';},onLoadError:()=>{document.querySelector('#error').hidden=false;document.body.dataset.loaded='error';}});}catch(err){document.querySelector('#error').hidden=false;document.body.dataset.loaded='error';console.error(err)}}pauseIcon();start();
